import { defineConfig } from '@prisma/config';

// =============================================================================
// Prisma configuration of the kvox-api test host (issue #492, epic #491)
// =============================================================================
//
// `prisma/schema/` and `prisma/migrations/` are GENERATED by `prepare.mjs`
// (platform fragments + the domain fragments of `@marinoscar/kvox-db`), and so
// is the client in `generated/`. Nothing under either is committed.
//
// The URL comes from the environment: `prepare.mjs` needs none (generating a
// client does not connect), and `db.ts` sets `DATABASE_URL` to the throwaway
// database it created before it runs `prisma migrate deploy`.
// =============================================================================

export default defineConfig({
  schema: 'prisma/schema',
  datasource: {
    url: process.env.DATABASE_URL ?? 'postgresql://postgres:postgres@localhost:5432/postgres',
  },
  migrations: {
    path: 'prisma/migrations',
  },
});
